#!/usr/bin/env bash
# Renders per-language version metadata from proto/VERSION.
# Output files are committed; regeneration is idempotent for the same VERSION.
set -euo pipefail

VERSION_FILE="proto/VERSION"
if [ ! -f "$VERSION_FILE" ]; then
    echo "error: $VERSION_FILE not found (run 'make update-version' first)" >&2
    exit 1
fi

REF=$(jq -r .nacos_ref "$VERSION_FILE")
COMMIT=$(jq -r .nacos_commit "$VERSION_FILE")

cat > go/version.go << EOF
// Code generated by render-version.sh from proto/VERSION. DO NOT EDIT.

package _go

// NacosRef is the nacos ref (tag or branch) the protos were generated from.
const NacosRef = "${REF}"

// NacosCommit is the exact alibaba/nacos commit the protos were generated from.
const NacosCommit = "${COMMIT}"
EOF

mkdir -p nodejs/src
cat > nodejs/src/version.ts << EOF
// Code generated by render-version.sh from proto/VERSION. DO NOT EDIT.

/** The nacos ref (tag or branch) the protos were generated from. */
export const NACOS_REF = "${REF}";

/** The exact alibaba/nacos commit the protos were generated from. */
export const NACOS_COMMIT = "${COMMIT}";
EOF

mkdir -p python/nacos_sdk_proto
cat > python/nacos_sdk_proto/version.py << EOF
# Code generated by render-version.sh from proto/VERSION. DO NOT EDIT.

NACOS_REF = "${REF}"
NACOS_COMMIT = "${COMMIT}"
EOF

echo "Rendered version metadata: nacos_ref=${REF} nacos_commit=${COMMIT:0:7}"
